interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

/** Mutable working state threaded through the event handlers. */
interface FulfillState {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

/** The fields an event carries, read loosely from the raw payload. */
interface EventFields {
  id?: string;
  item?: string;
  qty?: number;
}

/** One event handler: mutates state, returns an error reason or undefined. */
type Handler = (ev: EventFields, state: FulfillState) => string | undefined;

// Dispatch by event type - collapses the per-type branch chain into a lookup.
const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: FulfillState = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const rawEvent = input.events[index];
    if (typeof rawEvent !== "object" || rawEvent === null) {
      return fail("event " + index + ": ", "malformed");
    }
    const ev = rawEvent as Record<string, unknown>;
    const handler = HANDLERS[ev.type as string];
    if (handler === undefined) {
      return fail("event " + index + ": ", "bad type");
    }
    const error = handler(ev as EventFields, state);
    if (error !== undefined) {
      return fail("event " + index + ": ", error);
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

function fail(prefix: string, reason: string): FulfillmentResult {
  return { ok: false, error: prefix + reason };
}

function badId(ev: EventFields): boolean {
  return typeof ev.id !== "string" || ev.id.length === 0;
}

function badItem(ev: EventFields): boolean {
  return typeof ev.item !== "string" || ev.item.length === 0;
}

function badQty(ev: EventFields): boolean {
  return typeof ev.qty !== "number" || !Number.isInteger(ev.qty) || ev.qty < 1;
}

function handleOrder(ev: EventFields, state: FulfillState): string | undefined {
  if (badId(ev)) return "bad id";
  if (state.orders[ev.id as string] !== undefined) return "duplicate order";
  if (badItem(ev)) return "bad item";
  if (badQty(ev)) return "bad qty";
  const want: Want = { item: ev.item as string, qty: ev.qty as number };
  const onHand = state.stock[want.item] ?? 0;
  if (onHand >= want.qty) {
    state.stock[want.item] = onHand - want.qty;
    state.reserved[ev.id as string] = want;
    state.orders[ev.id as string] = "reserved";
  } else {
    state.queue.push(ev.id as string);
    state.pendingWants[ev.id as string] = want;
    state.orders[ev.id as string] = "backordered";
  }
}

function handleCancel(ev: EventFields, state: FulfillState): string | undefined {
  if (badId(ev)) return "bad id";
  if (state.reserved[ev.id as string] !== undefined) {
    const holding = state.reserved[ev.id as string];
    state.stock[holding.item] = (state.stock[holding.item] ?? 0) + holding.qty;
    delete state.reserved[ev.id as string];
    state.orders[ev.id as string] = "cancelled";
    fillQueue(state);
  } else if (state.orders[ev.id as string] === "backordered") {
    state.queue.splice(state.queue.indexOf(ev.id as string), 1);
    delete state.pendingWants[ev.id as string];
    state.orders[ev.id as string] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function handleShip(ev: EventFields, state: FulfillState): string | undefined {
  if (badId(ev)) return "bad id";
  if (ev.qty !== undefined && badQty(ev)) return "bad qty";
  const holding = state.reserved[ev.id as string];
  if (holding === undefined) {
    state.rejected = state.rejected + 1;
  } else if (ev.qty === undefined || ev.qty === holding.qty) {
    delete state.reserved[ev.id as string];
    state.orders[ev.id as string] = "shipped";
  } else if (ev.qty < holding.qty) {
    holding.qty = holding.qty - ev.qty;
    state.orders[ev.id as string] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function handleRestock(ev: EventFields, state: FulfillState): string | undefined {
  if (badItem(ev)) return "bad item";
  if (badQty(ev)) return "bad qty";
  state.stock[ev.item as string] = (state.stock[ev.item as string] ?? 0) + (ev.qty as number);
  fillQueue(state);
}

function handleExpire(ev: EventFields, state: FulfillState): string | undefined {
  if (badId(ev)) return "bad id";
  if (state.reserved[ev.id as string] !== undefined) {
    const holding = state.reserved[ev.id as string];
    state.stock[holding.item] = (state.stock[holding.item] ?? 0) + holding.qty;
    delete state.reserved[ev.id as string];
    state.orders[ev.id as string] = "expired";
    fillQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
}

/** Refill waiting backorders with newly available stock. */
function fillQueue(state: FulfillState): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHand = state.stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      state.stock[want.item] = onHand - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

