      if (event.qty !== undefined && (!Number.isInteger(event.qty) || event.qty < 1)) return { ok: false, error: "event " + index + ": bad qty" };
      if (reserved[event.id] === undefined) { rejected = rejected + 1; }
      else if (event.qty === undefined || event.qty === reserved[event.id].qty) { delete reserved[event.id]; orders[event.id] = "shipped"; }
      else if (event.qty < reserved[event.id].qty) { reserved[event.id].qty = reserved[event.id].qty - event.qty; orders[event.id] = "partial"; }
