      } else { rejected = rejected + 1; }
    } else { return { ok: false, error: "event " + index + ": bad type" }; }
  }
  return { ok: true, orders, stock, queue, rejected, report: BUILD(orders, rejected) };

  function BUILD(o: Record<string,string>, r: number): string {
